import{_ as s,o as t,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0046 — Profils d'usage : une instance naît avec les extensions de son métier","description":"Extrait de docs/adr/0046-profils-d-usage-a-l-installation.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0046 — Profils d'usage : une instance naît avec les extensions de son métier","description":"Extrait de docs/adr/0046-profils-d-usage-a-l-installation.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0046-profils-d-usage-a-l-installation.md","filePath":"developpeurs/adr/0046-profils-d-usage-a-l-installation.md"}`),a={name:"developpeurs/adr/0046-profils-d-usage-a-l-installation.md"};function o(l,e,r,d,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0046--profils-dusage--une-instance-naît-avec-les-extensions-de-son-métier" tabindex="-1">ADR-0046 — Profils d&#39;usage : une instance naît avec les extensions de son métier <a class="header-anchor" href="#adr-0046--profils-dusage--une-instance-naît-avec-les-extensions-de-son-métier" aria-label="Permalink to &quot;ADR-0046 — Profils d&#39;usage : une instance naît avec les extensions de son métier {#adr-0046--profils-dusage--une-instance-naît-avec-les-extensions-de-son-métier}&quot;">​</a></h1><p><strong>Date :</strong> 24 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> plan de déploiement du 24/09/2026, décisions D4, D11 et D12 ; prolonge l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0028-packs-verticaux-du-catalogue-livre">ADR-0028</a> (packs verticaux) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0026-installation-guidee-cle-d-installation">ADR-0026</a> (écran d&#39;installation) ; tenu par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0002-frontiere-core-plugins">ADR-0002</a> (frontière Core/plugins)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0028 a organisé le catalogue en cinq packs. Un pack n&#39;y est qu&#39;une convention de lecture : il ne s&#39;installe pas d&#39;un coup. Qui veut un site de collectivité doit donc installer une vingtaine d&#39;extensions, une par une, depuis l&#39;écran Plugins. Il doit savoir lesquelles, et dans quel ordre, puisque certaines en référencent d&#39;autres.</p><p>Le Product Owner veut que le déploiement s&#39;adapte à l&#39;usage. On choisit un métier au départ, et l&#39;instance naît avec les extensions qui lui conviennent, comme les profils d&#39;installation de Drupal.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Un profil est un fichier déclaratif livré avec le catalogue, dans <code>app/bundled_plugins/profiles/*.yaml</code> (D4).</strong> Il déclare :</p><ul><li>les extensions à installer ;</li><li>les permissions accordées, toujours explicites ;</li><li>les pages de départ ;</li><li>les vues liste ;</li><li>le thème du front (ADR-0047).</li></ul><p>Le Core lit ces fichiers <strong>sans connaître leur contenu</strong>, comme il lit déjà les manifestes. Aucun nom de plugin n&#39;entre dans le code du Core, et l&#39;ADR-0002 n&#39;a besoin d&#39;aucune exception. Un profil qui nomme une extension inconnue fait <strong>refuser le démarrage</strong>, parce qu&#39;un profil qui promet une extension absente ne doit jamais s&#39;installer à moitié.</p><p><strong>2. Cinq profils en v1.</strong></p><ul><li><strong>Collectivité</strong> : le pack secteur public.</li><li><strong>Blog et presse</strong> : Actualités, Rédaction, Annuaire de personnes, Publications, Albums et Navigation.</li><li><strong>Portfolio</strong> : Albums, Agence, Paroles d&#39;acteurs, et Annuaire de personnes en option.</li><li><strong>Catalogue et devis</strong> : Boutique, Albums, Paroles d&#39;acteurs et Cartographie.</li><li><strong>Sur mesure (headless)</strong> : le Core seul, sans front.</li></ul><p><strong>3. Chaque profil dit ce qu&#39;il ne fait pas, avant qu&#39;on le choisisse.</strong></p><ul><li>L&#39;usage « e-commerce » s&#39;appelle <strong>« Catalogue et devis »</strong> : il n&#39;a ni panier, ni paiement, ni commande (ADR-0028, règle n°3).</li><li><strong>« Blog et presse » ne promet pas de commentaires (D11).</strong> L&#39;extension Commentaires n&#39;est qu&#39;une démonstration, sans stockage ni modération. De vrais commentaires modérés feront l&#39;objet d&#39;un Epic à part, s&#39;ils sont demandés.</li></ul><p><strong>4. Le profil se choisit à l&#39;écran d&#39;installation, qui gagne l&#39;étape « Quel est votre projet ? ».</strong></p><ul><li>L&#39;installateur peut le présélectionner (<code>--profil</code>).</li><li>Il s&#39;applique dans <strong>la même transaction</strong> que l&#39;installation : si le profil échoue, rien n&#39;est installé.</li><li>Le profil appliqué est conservé dans les réglages de l&#39;organisation.</li></ul><p><strong>5. Un profil est un point de départ, pas une cage.</strong> Chaque extension reste installable et désinstallable une par une ensuite. Désinstaller une extension ne retire jamais les contenus créés avec elle.</p><p><strong>6. Un profil n&#39;accorde jamais de permission sensible en silence.</strong> En particulier, <code>ai.invoke</code> (CDC §15.2) ne figure dans aucun profil.</p><p><strong>7. Le profil « Produit logiciel », construit sur le pack Développeurs, vient après le deuxième jalon (D12).</strong> Le pack reste installable à la main d&#39;ici là.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Des profils écrits en Python dans <code>bundled_plugins</code></td><td>Plus souples, mais illisibles pour un non-développeur. Le site du projet devrait exécuter du code pour les décrire (ADR-0048).</td></tr><tr><td>Un mécanisme de dépendances entre plugins (<code>requires</code>)</td><td>L&#39;ADR-0028 l&#39;a écarté tant que la gêne n&#39;est pas quotidienne. Un profil liste explicitement tout ce qu&#39;il installe, et le problème ne se pose pas.</td></tr><tr><td>Garder le nom « E-commerce »</td><td>Il promettrait une vente en ligne que le catalogue ne fait pas. Le premier exploitant déçu le serait à juste titre.</td></tr><tr><td>Construire les commentaires avant le thème Blog</td><td>Une à deux semaines de plus avant le premier site visible, pour une fonction que personne n&#39;a encore demandée.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>On installe un métier en un choix, au lieu de vingt installations dans le bon ordre.</li><li>Le catalogue du site du projet (ADR-0048) se génère à partir des mêmes fichiers : il ne peut pas dériver du code.</li><li>Chaque profil a son test, qui compare la liste exacte des extensions installées.</li></ul><p><strong>Négatives</strong></p><ul><li>Chaque nouvelle extension demande de décider dans quels profils elle entre.</li><li>Le vocabulaire des extensions réutilisées reste marqué par le secteur public. L&#39;ADR-0028 le signalait déjà : un portfolio installe « Albums » et « Paroles d&#39;acteurs ».</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Mécanisme des profils : format validé au démarrage, service <code>apply_profile</code> qui ne commite pas et réutilise <code>install_plugin</code>, étape « Quel est votre projet ? » de l&#39;écran d&#39;installation, profil conservé dans les réglages de l&#39;organisation. — <code>app/profiles/</code> (schéma, chargeur validé au démarrage contre le catalogue de plugins et le registre de blocs, <code>apply_profile</code>, espace de réglages <code>profile</code>), câblé par <code>app/bundled_plugins/usage_profiles.py</code> et <code>app/composition.py</code> sans qu&#39;aucun nom de plugin n&#39;entre dans le Core ; création de page extraite de <code>POST /pages</code> dans <code>app/page_builder/pages.py</code> ; <code>GET /api/v1/installation/profiles</code> et <code>profile</code> dans <code>POST /api/v1/installation</code> (absent = <code>sur_mesure</code>) ; étape « Quel est votre projet ? » de <code>apps/admin/pages/installation.vue</code> (présélection par <code>?profil=</code>).</li><li>[x] Les cinq profils, avec leurs pages de départ en français et un test par profil. — <code>app/bundled_plugins/profiles/*.yaml</code> (<code>collectivite</code>, <code>blog_presse</code>, <code>portfolio</code>, <code>catalogue_devis</code>, <code>sur_mesure</code>) ; recette <code>apps/api/tests/test_profiles.py</code> (extensions et pages exactes par profil, refus avant écriture, échec en cours d&#39;application sans rien laisser, désinstallation après coup) et chargement des cinq profils depuis l&#39;image de production (<code>.github/scripts/verifier-images.sh</code>).</li><li>[ ] Profil « Produit logiciel » (pack Développeurs), après le deuxième jalon.</li></ul>',27)])])}const m=s(a,[["render",o]]);export{g as __pageData,m as default};
